(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.4)*20 + Math.cos(y*0.012-t*0.3)*15;
  const w1y = Math.cos(y*0.02-t*0.35)*20 + Math.sin(x*0.015+t*0.45)*15;
  const w2x = Math.sin((x+y)*0.01+t*0.2)*12 + Math.cos((x-y)*0.015-t*0.5)*8;
  const w2y = Math.cos((x-y)*0.012+t*0.25)*12 + Math.sin((x+y)*0.018-t*0.4)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const grav = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.07, 2.2, 1.0],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.45+1)*95, 0.055, 2.5, 1.1],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6, 0.85],
    [380+Math.sin(t*0.38+4)*100, 55+Math.cos(t*0.8+2)*75, 0.065, 2.8, 1.05],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*85, 0.08, 2.0, 0.95],
    [60+Math.sin(t*0.55+3)*70, 40+Math.cos(t*0.65)*50, 0.13, 1.4, 0.8],
    [420+Math.cos(t*0.42+2)*80, 200+Math.sin(t*0.48+1)*60, 0.075, 2.3, 1.0]
  ];
  let aS=0, iS=0, pE=0;
  for (const [gX,gY,f,sp,m] of grav) {
    const d = Math.sqrt((sx-gX)**2+(sy-gY)**2);
    const potential = m/(d*0.01+1);
    pE += potential;
    aS += Math.sin(d*f-t*sp)*potential*0.003;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.8)*potential*0.003;
  }
  const nE = pE/grav.length;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.9)+Math.sin(sx*0.028-sy*0.038+t*1.3))/2
    + Math.sin((sx+sy)*0.11+t*2.8)*0.25 + Math.sin((sx-sy)*0.095-t*2.2)*0.25
    + Math.sin(sx*0.06*sy*0.04+t*1.6)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const orbital = Math.sin(dist*0.04-ang*4-t*1.8)*0.5 + Math.sin(dist*0.055+ang*3-t*1.3)*0.35;
  const kinetic = (Math.abs(w1x)+Math.abs(w1y)+Math.abs(w2x)+Math.abs(w2y))*0.005;
  const conservation = 1.0/(1.0+kinetic*0.3);
  const raw = (aS-iS*0.65+bg*0.35+orbital*0.4)*conservation;
  const rd1 = Math.tanh(raw*2.8);
  const rd2 = Math.tanh((raw-0.15)*3.5+Math.sin(sx*0.12)*Math.sin(sy*0.12)*0.8);
  const reaction = Math.tanh((rd1*0.6+rd2*0.4)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.16)*Math.sin(sy*0.16)+Math.sin((sx+sy)*0.11+t)*0.6)*1.8)*0.25;
  const edge = 1.0/(Math.abs(reaction)+0.15)*0.15;
  const blend = reaction*0.65+cell*0.2+edge*0.15;
  const v = blend*0.5+0.5;
  const neon = [
    [2,2,12],[8,0,35],[20,0,80],[60,0,160],
    [0,60,200],[0,180,220],[0,255,180],[80,255,80],
    [200,255,0],[255,200,0],[255,100,0],[255,30,60],
    [255,0,180],[200,0,255],[120,0,200],[60,0,120],[2,2,12]
  ];
  const idx = v*(neon.length-1), i = Math.min(idx|0, neon.length-2), f = idx-i;
  const lum = 0.75+Math.abs(reaction)*0.45;
  const glow = Math.exp(-Math.abs(reaction)*0.8)*0.6+0.4;
  const bright = lum*glow;
  const hot = Math.max(0, Math.abs(reaction)-0.6)*2.5;
  return [
    Math.min(255, ((neon[i][0]+(neon[i+1][0]-neon[i][0])*f)*bright + hot*60)|0),
    Math.min(255, ((neon[i][1]+(neon[i+1][1]-neon[i][1])*f)*bright + hot*40)|0),
    Math.min(255, ((neon[i][2]+(neon[i+1][2]-neon[i][2])*f)*bright + hot*80)|0)
  ];
}
